WITH flattened AS (SELECT id, host, level, latency_ms, status_code, k, value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS k, value) SELECT *, STDDEV_SAMP(latency_ms) OVER w_grp AS level_stddev_samp_latency_ms, CORR(latency_ms, status_code) OVER w_grp AS corr_latency_ms_status_code, ROUND(latency_ms / SUM(latency_ms) OVER (PARTITION BY host), 4) AS latency_ms_share FROM flattened WINDOW w_grp AS (PARTITION BY level);
